package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.*;import java.io.*;import org.json.*;
public class Regression0525Test {
 @Test public void sharedSampleRulesPreserveRealTitlesAndExcludeNestedClips(){for(String path:List.of("Sample.Size.2019.1080p/Sample.Size.2019.mkv","Movie/Resampled.Audio.Pack/track.flac","The.Sample.Show.S01/E01.mkv"))assertTrue(path,DownloadStation.defaultSelected(path));assertFalse(MediaLogic.sample("Sample Size.mkv"));assertTrue(MediaLogic.video("Sample.Size.2019.mkv"));assertFalse(DownloadStation.defaultSelected("Movie/Samples/clip.mkv"));assertFalse(DownloadStation.defaultSelected("Movie/Show.sample.mkv"));String root=MediaLogic.torrentRoot(List.of("Samples/S01E01.mkv","Samples/S01E02.mkv"));assertTrue(DownloadStation.defaultSelected("Samples/S01E01.mkv",root));assertEquals("",MediaLogic.torrentRoot(List.of("Movie.mkv","Samples/clip.mkv")));assertFalse(DownloadStation.defaultSelected("Samples/clip.mkv",""));assertFalse(MediaDeletion.sample("/Samples/Show/S01E01.mkv",List.of("/Samples/Show")));assertTrue(MediaDeletion.sample("/Samples/Show/Samples/clip.mkv",List.of("/Samples/Show")));}
 @Test public void missingApisReportTheActualOperation()throws Exception{for(String api:List.of("SYNO.FileStation.Delete","SYNO.FileStation.Upload"))try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient c=f.client();f.missingApi=api;IOException error=assertThrows(IOException.class,()->{if(api.endsWith("Delete"))c.deleteMediaPaths(List.of("/video/a.mkv"));else c.savePairing("/video","/video/a.mkv",true,new JSONObject().put("id",12));});assertFalse(error.getMessage(),error.getMessage().contains("Download Station"));assertTrue(error.getMessage(),error.getMessage().contains(api.endsWith("Delete")?"törlési":"párosítás"));}}
 @Test public void publicHttpConsentIsCheckedBeforeInitialAndReconnectRequests()throws Exception{NasClient.Credentials publicProfile=new NasClient.Credentials("http://nas.example.invalid:5000","","fixture","fixture","");AtomicInteger probes=new AtomicInteger();NasClient c=new NasClient(publicProfile,null,url->{probes.incrementAndGet();return true;}).withHttpConsent(values->HttpConsent.pending(values,key->false).isEmpty());assertThrows(SecurityException.class,c::connect);assertEquals(0,probes.get());try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){NasClient root=f.client().withHttpConsent(values->false);assertThrows(SecurityException.class,()->root.reconnectCandidate(false));assertEquals(1,f.logins.get());}}
 @Test public void httpConsentMessagesHaveEnglishAndHungarianResources()throws Exception{Map<String,String> en=LocalisationResourcesTest.strings("values"),hu=LocalisationResourcesTest.strings("values-hu");for(String key:List.of("http_consent_title","http_consent_message","http_consent_accept","http_consent_pending")){assertNotEquals(en.get(key),hu.get(key));assertNotNull(en.get(key));}}
 static NasClient.Entry entry(int n,long modified){String id=String.format(java.util.Locale.ROOT,"%032x",n);NasClient.Entry e=new NasClient.Entry(id+".json","/root/.synostream/parositasok/"+id+".json",false,300);e.modified=modified;return e;}
 static byte[] event(NasClient.Entry e,long gen)throws Exception{return new JSONObject().put("format_version",1).put("event_id",e.name.substring(0,32)).put("relative_path","Movie.mkv").put("media_type","movie").put("tmdb_id",10).put("title","Fixture").put("deleted",false).put("generation",gen).put("created_ns",1).toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test public void moreThan4096EventsDoNotThrashOrHideChangedEntries()throws Exception{PairingGenerationIndex index=new PairingGenerationIndex();List<NasClient.Entry> entries=new ArrayList<>();for(int n=1;n<=5000;n++)entries.add(entry(n,1));AtomicInteger reads=new AtomicInteger();PairingGenerationIndex.Read source=e->{reads.incrementAndGet();return event(e,1);};assertEquals(1,index.generation("account/root",entries,"Movie.mkv",true,source));assertEquals(5000,reads.get());assertEquals(1,index.generation("account/root",entries,"Movie.mkv",true,source));assertEquals(5000,reads.get());entries.get(1).modified=2;assertEquals(1,index.generation("account/root",entries,"Movie.mkv",true,source));assertEquals(5001,reads.get());assertEquals(1,index.generation("other/root",entries,"Movie.mkv",true,source));assertEquals(10001,reads.get());}
 @Test public void unknownTimestampsRemainUntrusted()throws Exception{PairingGenerationIndex index=new PairingGenerationIndex();List<NasClient.Entry> entries=List.of(entry(1,0));AtomicInteger reads=new AtomicInteger();for(int n=0;n<2;n++)assertEquals(4,index.generation("account",entries,"Movie.mkv",true,e->{reads.incrementAndGet();return event(e,4);}));assertEquals(2,reads.get());}
 @Test public void reconnectRetainsValidatedPairingIndex()throws Exception{try(NasClientConcurrencyTest.Fixture f=new NasClientConcurrencyTest.Fixture()){String id="a".repeat(32);f.pairingFiles.put(id+".json",ClaudeReviewTest.event(id,7));NasClient root=f.client();root.savePairing("/video","/video/movie.mkv",true,new JSONObject().put("id",11));int before=f.pairingReads.get();NasClient next=root.reconnectCandidate(true);int generation=root.suspendConnection();assertTrue(root.installConnection(generation,next));root.savePairing("/video","/video/movie.mkv",true,new JSONObject().put("id",12));assertEquals(before+2,f.pairingReads.get());}}
}
